const rows = $input.all().map(i => i.json);
const symbolSet = new Set(rows.map(r => r.symbol));
const symbols = Array.from(symbolSet);

const CHUNK_SIZE = 5;
const chunks = [];
for (let i = 0; i < symbols.length; i += CHUNK_SIZE) {
  chunks.push(symbols.slice(i, i + CHUNK_SIZE));
}

return chunks.map((chunk, idx) => ({ json: { chunk_index: idx, symbols: chunk } }));

const chunk = $('Loop Over Chunks').first().json;
const symbolList = chunk.symbols;
const allRows = $('Get Multi-Timeframe Prices').all().map(i => i.json);
const rows = allRows.filter(r => symbolList.includes(r.symbol));

const groups = {};
for (const r of rows) {
  const key = r.symbol + '|' + r.timeframe;
  if (!groups[key]) groups[key] = [];
  groups[key].push(r);
}

const tfLabel = { '1h': 'ngan han (1h, ~30 ngay)', '4h': 'trung han (4h, ~30 ngay)', '1d': 'dai han (1d, ~1 thang)' };
const lastPrices = {};
const summaryBySymbol = {};

for (const symbol of symbolList) {
  const lines = [];
  for (const tf of ['1h', '4h', '1d']) {
    const arr = groups[symbol + '|' + tf];
    if (!arr || arr.length === 0) continue;
    const first = parseFloat(arr[0].close);
    const last = parseFloat(arr[arr.length - 1].close);
    const changePct = first > 0 ? (((last - first) / first) * 100).toFixed(2) : '0';
    const high = Math.max(...arr.map(a => parseFloat(a.close)));
    const low = Math.min(...arr.map(a => parseFloat(a.close)));
    lines.push(`  - ${tfLabel[tf]}: tu ${first} den ${last} (${changePct}%), cao nhat ${high.toFixed(4)}, thap nhat ${low.toFixed(4)}`);
    lastPrices[symbol] = last;
  }
  summaryBySymbol[symbol] = lines.length ? lines.join('\n') : '  (khong du du lieu)';
}

const dataText = symbolList.map(s => `${s}:\n${summaryBySymbol[s]}`).join('\n\n');

const prompt = `Ban la AI phan tich thi truong crypto, ket hop nhieu khung thoi gian de danh gia xu huong tong the.\nDu lieu:\n\n${dataText}\n\nTra loi DUY NHAT mot JSON array, khong them chu nao khac, khong dung markdown code block, dung format:\n[{"symbol": "BTCUSDT", "signal": "BUY|SELL|HOLD", "confidence": 0-100, "reason": "giai thich ngan gon dua tren ca 3 khung thoi gian"}]\n\nconfidence la muc do tin cay cua chinh ban vao du doan nay (0=khong chac chan, 100=rat chac chan), dua tren muc do dong nhat cua xu huong giua cac khung thoi gian.\n\nPhai co du 1 object cho moi symbol: ${symbolList.join(', ')}`;

return [{ json: { prompt, last_prices: lastPrices, symbol_list: symbolList } }];

const raw = $input.first().json;
const lastPrices = $('Build Chunk Prompt').first().json.last_prices;
const symbolList = $('Build Chunk Prompt').first().json.symbol_list;

let contentText = '';
if (raw.choices && raw.choices[0] && raw.choices[0].message) {
  contentText = raw.choices[0].message.content || '';
} else if (raw.response) {
  contentText = raw.response;
}

const cleaned = contentText.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = [];
}

if (parsed && !Array.isArray(parsed) && typeof parsed === "object") {
  parsed = Object.entries(parsed).map(([key, val]) => ({
    symbol: (val && val.symbol) || key,
    signal: val ? val.signal : undefined,
    confidence: val ? val.confidence : undefined,
    reason: val ? val.reason : undefined
  }));
}

if (!Array.isArray(parsed) || parsed.length === 0) {
  parsed = symbolList.map(symbol => ({
    symbol, signal: "HOLD", confidence: 0, reason: "parse_error: AI khong tra ve JSON hop le"
  }));
}

return parsed.map(p => {
  let conf = parseInt(p.confidence, 10);
  if (isNaN(conf)) conf = null;
  conf = conf === null ? null : Math.max(0, Math.min(100, conf));
  return {
    json: {
      symbol: p.symbol,
      signal: (p.signal || "HOLD").toUpperCase(),
      confidence: conf,
      reason: p.reason || "",
      price_at_signal: lastPrices[p.symbol] || null
    }
  };
});
